/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type SuccessDecayProps = Record<string, any>;

const SuccessDecay: React.FC<SuccessDecayProps> = ({
  backgroundColor = "#060608",
  transparentBackground = false,
  durationInSeconds = 10,
  text1 = "There's a version of success",
  text2 = "that looks impressive on the outside",
  text3 = "but is rotting underneath.",
  goldenColor1 = "#DFBA6B",
  goldenColor2 = "#8C6A2E",
  rotColor = "#4E5340",
  glowIntensity = 20,
  particleCount = 50,
  shatterIntensity = 5.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Unified proportional timing timeline
  const durationInFrames = durationInSeconds * fps;
  const f2 = durationInFrames * 0.08; // Text 1 fade-in starts
  const f3 = durationInFrames * 0.16; // Text 1 fully visible
  const f4 = durationInFrames * 0.20; // Text 2 fade-in starts
  const f_decay_start = durationInFrames * 0.44; // Glitch/Decay starts
  const f_decay_mid = durationInFrames * 0.54;   // Complete collapse
  const f6 = durationInFrames * 0.58; // Text 3 starts appearing
  const f7 = durationInFrames * 0.70; // Text 3 fully visible

  // Text 3 Dynamic Parsing (Robust fallback if text3 gets modified by user)
  const text3Lower = text3.toLowerCase();
  let text3Part1 = text3;
  let text3Part2 = "";

  const rottingIndex = text3Lower.indexOf("rotting");
  if (rottingIndex !== -1) {
    text3Part1 = text3.substring(0, rottingIndex).trim();
    text3Part2 = text3.substring(rottingIndex).trim();
  } else {
    const words = text3.split(" ");
    const mid = Math.ceil(words.length / 2);
    text3Part1 = words.slice(0, mid).join(" ");
    text3Part2 = words.slice(mid).join(" ");
  }

  // Camera Shake & Vibrations (Deterministic trigonometric calculations)
  const decayProgress = interpolate(
    frame,
    [f_decay_start, f_decay_mid],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const glitchStrength =
    interpolate(frame, [f_decay_start, f_decay_start + 15], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }) *
    interpolate(frame, [f_decay_mid - 5, f_decay_mid], [1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  // Shockwave impact on Text 3 appearance
  const impactProgress = interpolate(
    frame,
    [f6 + 10, f6 + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const impactShake = Math.sin(frame * 2.2) * 22 * (1 - impactProgress) * (frame > f6 + 10 ? 1 : 0);

  const shakeX = Math.sin(frame * 1.6) * 12 * glitchStrength + impactShake * 1.2;
  const shakeY = Math.cos(frame * 1.9) * 10 * glitchStrength + impactShake;

  // Background and border styling properties
  const currentBg = interpolateColors(
    frame,
    [f_decay_start, f_decay_mid],
    [backgroundColor, "#0a0c08"]
  );
  const bgStyle = transparentBackground ? "transparent" : currentBg;

  const borderOpacity = interpolate(
    frame,
    [0, 15, f_decay_start, f_decay_mid],
    [0, 0.5, 0.5, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const borderJitter = Math.sin(frame * 2.1) * 20 * glitchStrength;

  // Text 1 Animation calculations
  const t1Opacity = interpolate(
    frame,
    [f2, f3, f_decay_start, f_decay_mid],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const t1Scale = interpolate(
    frame,
    [f2, f3, f_decay_start, f_decay_mid],
    [1.06, 1, 1, 0.92],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const t1LetterSpacing = interpolate(
    frame,
    [f2, f_decay_start],
    [12, 3],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const t1Y = interpolate(
    frame,
    [f2, f3, f_decay_start, f_decay_mid],
    [15, 0, 0, 120],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Text 2 word splitting logic
  const t2Words = text2.split(" ");

  // Text 3 Entry Animations via custom spring
  const t3Spring = spring({
    fps,
    frame: Math.max(0, frame - (f6 + 8)),
    config: {
      damping: 10,
      mass: 0.9,
      stiffness: 110,
    },
  });

  const t3Scale = interpolate(t3Spring, [0, 1], [3.5, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const t3Opacity = interpolate(t3Spring, [0, 0.2, 1], [0, 1, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Background glow
  const glowOpacity = interpolate(
    frame,
    [0, 30, f_decay_start, f_decay_mid],
    [0, 1, 1, 0.15],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const glowColor = interpolateColors(
    frame,
    [f_decay_start, f_decay_mid],
    ["rgba(223, 186, 107, 0.15)", "rgba(78, 83, 64, 0.25)"]
  );

  // Dynamic deterministic particles
  const particlesArray = Array.from({ length: particleCount }).map((_, i) => {
    const seedX = random(`px-${i}`);
    const seedY = random(`py-${i}`);
    const speedY = 0.3 + random(`ps-${i}`) * 0.7;
    const size = 2 + random(`psize-${i}`) * 5;
    const wobbleSpeed = 0.015 + random(`pw-${i}`) * 0.02;
    const wobbleAmount = 6 + random(`pa-${i}`) * 12;
    return { seedX, seedY, speedY, size, wobbleSpeed, wobbleAmount };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgStyle,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        width: "100%",
        height: "100%",
        overflow: "hidden",
        position: "relative",
        transform: `translate(${shakeX}px, ${shakeY}px)`,
        transition: "none",
      }}
    >
      {/* Background vignette & radial glow */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "radial-gradient(circle, transparent 45%, rgba(0,0,0,0.85) 100%)",
          pointerEvents: "none",
          zIndex: 2,
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          width: width * 0.6,
          height: width * 0.6,
          background: `radial-gradient(circle, ${glowColor} 0%, transparent 70%)`,
          opacity: glowOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Particle Overlay */}
      <div style={{ position: "absolute", inset: 0, pointerEvents: "none", zIndex: 1 }}>
        {particlesArray.map((p, i) => {
          // Dynamic calculation of particle coordinates based on time
          const baseFloat = -frame * p.speedY;
          const fallDown = (frame - f_decay_start) * p.speedY * 8;
          const currentYOffset = interpolate(decayProgress, [0, 1], [baseFloat, fallDown]);
          
          const y = ((p.seedY * height + currentYOffset) % height + height) % height;
          const x = (p.seedX * width + Math.sin(frame * p.wobbleSpeed) * p.wobbleAmount) % width;

          const pColor = interpolateColors(
            decayProgress,
            [0, 1],
            [goldenColor1, rotColor]
          );

          const pOpacity = interpolate(
            frame,
            [0, 20, durationInFrames - 20, durationInFrames],
            [0, 0.45, 0.45, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: p.size,
                height: p.size,
                borderRadius: "50%",
                backgroundColor: pColor,
                opacity: pOpacity,
                boxShadow: decayProgress < 0.5 ? `0 0 8px ${goldenColor1}` : "none",
                transition: "none",
              }}
            />
          );
        })}
      </div>

      {/* Cinematic Elegant Border */}
      <div
        style={{
          position: "absolute",
          top: width * 0.04,
          left: width * 0.04,
          right: width * 0.04,
          bottom: width * 0.04,
          border: `${Math.max(1, Math.min(width, height) * 0.0015)}px solid ${goldenColor1}`,
          opacity: borderOpacity,
          pointerEvents: "none",
          zIndex: 3,
          transition: "none",
          transform: `scale(${interpolate(frame, [f_decay_start, f_decay_mid], [1, 0.94], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })}) rotate(${borderJitter * 0.04}deg)`,
        }}
      />

      {/* PHASE 1 & 2: Elegant Mirage Text Frame */}
      {frame < f_decay_mid + 15 && (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            textAlign: "center",
            width: "80%",
            maxWidth: width * 0.7,
            position: "absolute",
            zIndex: 4,
            transition: "none",
          }}
        >
          {/* Text 1 */}
          <div
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize: `${height * 0.032}px`,
              color: "#ffffff",
              opacity: t1Opacity,
              transform: `scale(${t1Scale}) translateY(${t1Y}px)`,
              letterSpacing: `${t1LetterSpacing}px`,
              textTransform: "uppercase",
              fontWeight: 300,
              marginBottom: "30px",
              transition: "none",
            }}
          >
            {text1}
          </div>

          {/* Text 2 (Staggered Word Collapse) */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              alignItems: "center",
              fontFamily: playfairFamily,
              fontSize: `${height * 0.06}px`,
              fontWeight: "bold",
              lineHeight: 1.25,
              transition: "none",
            }}
          >
            {t2Words.map((word, i) => {
              const wordDelay = i * 3.5;
              const wordStart = f4 + wordDelay;
              const wordEnd = wordStart + 15;

              // Staggered fade and slide entries
              const wordOpacity = interpolate(
                frame,
                [wordStart, wordEnd, f_decay_start + i * 2, f_decay_mid + i * 1.5],
                [0, 1, 1, 0],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              const wordY = interpolate(
                frame,
                [wordStart, wordEnd, f_decay_start + i * 2, f_decay_mid + i * 1.5],
                [18, 0, 0, 200 + i * shatterIntensity * 3],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              // Displace rotation during destruction
              const wordRotate = interpolate(
                frame,
                [f_decay_start + i * 2, f_decay_mid + i * 1.5],
                [0, i % 2 === 0 ? -12 : 12],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              );

              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    margin: "0 8px",
                    opacity: wordOpacity,
                    transform: `translateY(${wordY}px) rotate(${wordRotate}deg)`,
                    background: `linear-gradient(135deg, ${goldenColor1} 0%, ${goldenColor2} 100%)`,
                    WebkitBackgroundClip: "text",
                    WebkitTextFillColor: "transparent",
                    textShadow: `0 0 ${glowIntensity * (1 - decayProgress)}px rgba(223, 186, 107, 0.45)`,
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        </div>
      )}

      {/* PHASE 3: The Brutal Truth */}
      {frame >= f_decay_start && (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            textAlign: "center",
            width: "80%",
            maxWidth: width * 0.75,
            position: "absolute",
            zIndex: 5,
            transition: "none",
          }}
        >
          {/* "but is" */}
          <div
            style={{
              fontFamily: playfairFamily,
              fontSize: `${height * 0.038}px`,
              fontStyle: "italic",
              color: "#5f6452",
              opacity: interpolate(frame, [f6, f6 + 12], [0, 0.85], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              transform: `translateY(${interpolate(frame, [f6, f6 + 12], [-15, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })}px)`,
              marginBottom: "15px",
              transition: "none",
            }}
          >
            {text3Part1}
          </div>

          {/* "ROTTING UNDERNEATH." */}
          <div
            style={{
              fontFamily: spaceGroteskFamily,
              fontSize: `${height * 0.075}px`,
              fontWeight: 900,
              letterSpacing: "4px",
              color: rotColor,
              opacity: t3Opacity,
              transform: `scale(${t3Scale})`,
              textTransform: "uppercase",
              textShadow: `0 0 25px rgba(78, 83, 64, 0.5)`,
              transition: "none",
            }}
          >
            {text3Part2}
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default SuccessDecay;